xql_query:
// ============================================================
// Rule: CTX_Suspicious Svchost Execution from Temporary Directory
// Vendor: Cortex
// Objective:
// Detect activity associated with CTX_Suspicious Svchost Execution from Temporary Directory.
// Severity: SEV_040_HIGH
// Category: EXECUTION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0005 - Defense Evasion
// Technique: T1036.005 - Masquerading: Match Legitimate Name or Location

// Configuração inicial: comparações não diferenciam maiúsculas/minúsculas
// Objetivo: evitar perda de eventos por variações de caixa nos nomes e caminhos dos processos
config case_sensitive = false

// Fonte de dados: telemetria coletada pelo agente Cortex XDR/XSIAM
| dataset = xdr_data

// Filtro: restringe a eventos de inicialização de processos
// PROCESS_START = criação ou início de uma nova execução no endpoint
| filter event_type = ENUM.PROCESS
| filter event_sub_type = ENUM.PROCESS_START

// Filtro: procura processos executados com o nome svchost.exe
// O svchost.exe legítimo é um componente nativo do Windows utilizado para hospedar serviços
| filter action_process_image_name = "svchost.exe"

// Filtro: identifica execuções cujo caminho contém o diretório \Temp\
// Objetivo: detectar possíveis cópias ou binários maliciosos utilizando o nome svchost.exe
// fora dos diretórios legítimos do Windows, como:
// - C:\Windows\System32\svchost.exe
// - C:\Windows\SysWOW64\svchost.exe
| filter action_process_image_path ~= "(\\\\Temp\\\\)"

// Resultado final: apresenta os principais campos para investigação
| fields
    _time,                              // Data e hora da execução
    agent_hostname,                     // Host onde o processo foi executado
    actor_effective_username,           // Usuário efetivo associado à execução

    action_process_image_path,          // Caminho completo do svchost.exe executado
    action_process_image_command_line,  // Linha de comando do processo suspeito

    action_process_signature_status,    // Status da assinatura digital do svchost.exe
    action_process_signature_vendor,    // Fabricante identificado na assinatura digital

    actor_process_image_name,           // Processo pai responsável por iniciar o svchost.exe
    actor_process_command_line,          // Linha de comando do processo pai

    actor_process_signature_status,     // Status da assinatura digital do processo pai
    actor_process_signature_vendor,     // Fabricante da assinatura do processo pai

    causality_actor_process_image_path  // Caminho do processo de causalidade associado ao evento

// Ordenação: apresenta primeiro as execuções mais recentes
| sort desc _time
